/** Dynamically load the Google Maps JavaScript API (once). */

declare global {
  interface Window {
    google?: typeof google;
    __MMD_GOOGLE_MAPS_READY__?: Promise<typeof google>;
    __mmdGoogleMapsCb?: () => void;
  }
}

function mapCtorReady(g: typeof google | undefined): boolean {
  const MapCtor = g?.maps && (g.maps as { Map?: unknown }).Map;
  return typeof MapCtor === "function";
}

export async function loadGoogleMaps(apiKey: string): Promise<typeof google> {
  if (typeof window === "undefined") {
    throw new Error("Google Maps requires a browser");
  }
  if (mapCtorReady(window.google)) {
    return window.google!;
  }
  if (window.__MMD_GOOGLE_MAPS_READY__) {
    return window.__MMD_GOOGLE_MAPS_READY__;
  }

  window.__MMD_GOOGLE_MAPS_READY__ = new Promise((resolve, reject) => {
    const fail = (err: Error) => {
      window.__MMD_GOOGLE_MAPS_READY__ = undefined;
      reject(err);
    };

    const prevAuth = (window as Window & { gm_authFailure?: () => void }).gm_authFailure;
    (window as Window & { gm_authFailure?: () => void }).gm_authFailure = () => {
      try {
        prevAuth?.();
      } catch {
        /* ignore */
      }
      fail(new Error("Google Maps API key invalid or restricted"));
    };

    const finish = () => {
      if (!mapCtorReady(window.google)) {
        fail(new Error("Google Maps Map constructor unavailable after load"));
        return;
      }
      resolve(window.google!);
    };

    // Classic callback bootstrap — populates google.maps.Map reliably.
    const existing = document.querySelector<HTMLScriptElement>(
      'script[data-mmd-google-maps="1"]',
    );
    if (existing) {
      if (mapCtorReady(window.google)) {
        finish();
        return;
      }
      existing.addEventListener("load", () => finish());
      existing.addEventListener("error", () => fail(new Error("Google Maps script error")));
      return;
    }

    window.__mmdGoogleMapsCb = () => {
      try {
        finish();
      } finally {
        delete window.__mmdGoogleMapsCb;
      }
    };

    const script = document.createElement("script");
    script.dataset.mmdGoogleMaps = "1";
    script.async = true;
    script.defer = true;
    script.src =
      `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(apiKey)}` +
      `&v=weekly&callback=__mmdGoogleMapsCb`;
    script.onerror = () => fail(new Error("Google Maps script error"));
    document.head.appendChild(script);
  });

  return window.__MMD_GOOGLE_MAPS_READY__;
}
