/**
 * Mapbox GL–shaped facade over google.maps.Map so diary-app can share most
 * route / camera / marker call sites on the Google MVP path.
 */

import { GoogleLngLatBounds } from "./google-bounds";
import type { GoogleMapHost } from "./google-marker";

type LngLat = [number, number] | { lng: number; lat: number };

type GeoJSONFeature = {
  type?: string;
  geometry?: { type?: string; coordinates?: number[][] };
};

type SourceRecord = {
  data: GeoJSONFeature | null;
  layers: Set<string>;
};

type LayerRecord = {
  id: string;
  source: string;
  type: string;
  polyline: google.maps.Polyline;
  visibility: "visible" | "none";
  color: string;
  opacity: number;
  weight: number;
};

type EaseOpts = {
  center?: LngLat;
  zoom?: number;
  pitch?: number;
  bearing?: number;
  padding?: number | { top?: number; bottom?: number; left?: number; right?: number };
  duration?: number;
  essential?: boolean;
};

type FitBoundsOpts = EaseOpts & {
  maxZoom?: number;
  minZoom?: number;
};

function asLngLat(input: LngLat): { lng: number; lat: number } {
  if (Array.isArray(input)) return { lng: Number(input[0]), lat: Number(input[1]) };
  return { lng: Number(input.lng), lat: Number(input.lat) };
}

function coordsFromFeature(data: GeoJSONFeature | null): google.maps.LatLngLiteral[] {
  const coords = data?.geometry?.coordinates;
  if (!Array.isArray(coords)) return [];
  return coords
    .map((c) => ({ lng: Number(c[0]), lat: Number(c[1]) }))
    .filter((c) => Number.isFinite(c.lng) && Number.isFinite(c.lat));
}

/** Mapbox interpolate expressions → a mid-range constant for Google polylines. */
function resolveWidth(value: unknown, fallback = 3): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (Array.isArray(value) && value[0] === "interpolate") {
    const nums = value.filter((v): v is number => typeof v === "number");
    if (nums.length >= 2) {
      // pick a mid zoom width (odd indices after zoom stops are widths)
      const widths: number[] = [];
      for (let i = 3; i < value.length; i += 2) {
        if (typeof value[i + 1] === "number") widths.push(value[i + 1] as number);
      }
      if (widths.length) return widths[Math.floor(widths.length / 2)] || fallback;
    }
  }
  return fallback;
}

function resolveOpacity(value: unknown, fallback = 1): number {
  if (typeof value === "number" && Number.isFinite(value)) return Math.max(0, Math.min(1, value));
  return fallback;
}

function resolveColor(value: unknown, fallback = "#38bdf8"): string {
  return typeof value === "string" && value ? value : fallback;
}

export type GoogleMapShimOptions = {
  container: string | HTMLElement;
  center?: LngLat;
  zoom?: number;
  pitch?: number;
  bearing?: number;
  maxPitch?: number;
};

export class GoogleMapShim {
  readonly provider = "google" as const;
  readonly __mmdGoogleHost: GoogleMapHost;
  gmap: google.maps.Map;
  maps: typeof google.maps;

  private sources = new Map<string, SourceRecord>();
  private layers = new Map<string, LayerRecord>();
  private listeners = new Map<string, Set<(...args: unknown[]) => void>>();
  private styleLoaded = false;
  private destroyed = false;
  private containerEl: HTMLElement;

  constructor(g: typeof google, opts: GoogleMapShimOptions) {
    this.maps = g.maps;
    this.containerEl =
      typeof opts.container === "string"
        ? (document.getElementById(opts.container) as HTMLElement)
        : opts.container;
    if (!this.containerEl) throw new Error("Google map container not found");

    const center = asLngLat(opts.center || [-109.5, 36.8]);
    this.gmap = new this.maps.Map(this.containerEl, {
      center: { lat: center.lat, lng: center.lng },
      zoom: opts.zoom ?? 3.85,
      tilt: opts.pitch ?? 45,
      heading: opts.bearing ?? 0,
      mapTypeId: "hybrid",
      disableDefaultUI: false,
      zoomControl: true,
      mapTypeControl: false,
      streetViewControl: false,
      fullscreenControl: false,
      rotateControl: true,
      gestureHandling: "greedy",
      clickableIcons: false,
      keyboardShortcuts: true,
    });

    this.__mmdGoogleHost = { gmap: this.gmap, maps: this.maps };

    this.maps.event.addListenerOnce(this.gmap, "idle", () => {
      this.styleLoaded = true;
      this.emit("load");
      this.emit("styledata");
    });
    this.gmap.addListener("idle", () => {
      this.emit("moveend");
      this.emit("zoomend");
    });
    this.gmap.addListener("zoom_changed", () => this.emit("zoomend"));
  }

  /** Allow GoogleHtmlMarker.addTo(map) to find the host. */
  get _googleHost(): GoogleMapHost {
    return this.__mmdGoogleHost;
  }

  on(event: string, fn: (...args: unknown[]) => void): this {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event)!.add(fn);
    return this;
  }

  off(event: string, fn: (...args: unknown[]) => void): this {
    this.listeners.get(event)?.delete(fn);
    return this;
  }

  private emit(event: string, ...args: unknown[]): void {
    this.listeners.get(event)?.forEach((fn) => {
      try {
        fn(...args);
      } catch (err) {
        console.error(err);
      }
    });
  }

  isStyleLoaded(): boolean {
    return this.styleLoaded;
  }

  getStyle(): { layers: { id: string; type: string }[] } {
    return { layers: [] };
  }

  getContainer(): HTMLElement {
    return this.containerEl;
  }

  getCanvas(): HTMLCanvasElement {
    return this.containerEl.querySelector("canvas") || document.createElement("canvas");
  }

  getCanvasContainer(): HTMLElement {
    return this.containerEl;
  }

  getZoom(): number {
    return this.gmap.getZoom() ?? 4;
  }

  getPitch(): number {
    return this.gmap.getTilt?.() ?? 0;
  }

  getBearing(): number {
    return this.gmap.getHeading?.() ?? 0;
  }

  getCenter(): { lng: number; lat: number; toArray: () => [number, number] } {
    const c = this.gmap.getCenter();
    const lng = c?.lng() ?? 0;
    const lat = c?.lat() ?? 0;
    return { lng, lat, toArray: () => [lng, lat] };
  }

  project(lngLat: LngLat): { x: number; y: number } {
    // Export compositing is Mapbox-only; stub for Google MVP.
    void lngLat;
    return { x: 0, y: 0 };
  }

  stop(): void {
    /* Google has no pending ease queue to cancel */
  }

  setTerrain(_opts?: unknown): void {
    /* DEM not available on Google hybrid MVP */
  }

  addControl(_control: unknown, _position?: string): this {
    return this;
  }

  /** Interaction shims — Google Map handles gestures natively. */
  dragPan = { enable() {}, disable() {} };
  scrollZoom = { enable() {}, disable() {} };
  boxZoom = { enable() {}, disable() {} };
  dragRotate = { enable() {}, disable() {} };
  keyboard = { enable() {}, disable() {} };
  doubleClickZoom = { enable() {}, disable() {} };
  touchZoomRotate = { enable() {}, disable() {} };
  touchPitch = { enable() {}, disable() {} };

  addSource(id: string, spec: { type?: string; data?: GeoJSONFeature; lineMetrics?: boolean }): this {
    this.sources.set(id, { data: spec.data || null, layers: new Set() });
    return this;
  }

  getSource(id: string): { setData: (data: GeoJSONFeature) => void } | undefined {
    const src = this.sources.get(id);
    if (!src) return undefined;
    return {
      setData: (data: GeoJSONFeature) => {
        src.data = data;
        const path = coordsFromFeature(data);
        src.layers.forEach((layerId) => {
          const layer = this.layers.get(layerId);
          if (layer) layer.polyline.setPath(path);
        });
      },
    };
  }

  addLayer(layer: {
    id: string;
    type: string;
    source: string;
    layout?: Record<string, unknown>;
    paint?: Record<string, unknown>;
  }): this {
    const src = this.sources.get(layer.source);
    if (!src) return this;
    const paint = layer.paint || {};
    const layout = layer.layout || {};
    const color = resolveColor(paint["line-color"], "#38bdf8");
    const opacity = resolveOpacity(paint["line-opacity"], 1);
    const weight = resolveWidth(paint["line-width"], 3);
    const visibility = layout.visibility === "none" ? "none" : "visible";
    const path = coordsFromFeature(src.data);

    const polyline = new this.maps.Polyline({
      path,
      map: visibility === "visible" ? this.gmap : null,
      strokeColor: color,
      strokeOpacity: opacity,
      strokeWeight: weight,
      geodesic: true,
      clickable: false,
      zIndex: layer.id.includes("casing") ? 1 : layer.id.includes("core") ? 3 : 2,
    });

    src.layers.add(layer.id);
    this.layers.set(layer.id, {
      id: layer.id,
      source: layer.source,
      type: layer.type,
      polyline,
      visibility,
      color,
      opacity,
      weight,
    });
    return this;
  }

  getLayer(id: string): LayerRecord | undefined {
    return this.layers.get(id);
  }

  setPaintProperty(id: string, prop: string, value: unknown): void {
    const layer = this.layers.get(id);
    if (!layer) return;
    if (prop === "line-color") {
      layer.color = resolveColor(value, layer.color);
      layer.polyline.setOptions({ strokeColor: layer.color });
    } else if (prop === "line-opacity") {
      layer.opacity = resolveOpacity(value, layer.opacity);
      layer.polyline.setOptions({ strokeOpacity: layer.opacity });
    } else if (prop === "line-width") {
      layer.weight = resolveWidth(value, layer.weight);
      layer.polyline.setOptions({ strokeWeight: layer.weight });
    }
    // line-blur / line-offset / line-emissive-strength / dash: ignored on Google MVP
  }

  setLayoutProperty(id: string, prop: string, value: unknown): void {
    const layer = this.layers.get(id);
    if (!layer) return;
    if (prop === "visibility") {
      layer.visibility = value === "none" ? "none" : "visible";
      layer.polyline.setMap(layer.visibility === "visible" ? this.gmap : null);
    }
  }

  removePaintProperty(_id: string, _prop: string): void {
    /* no-op */
  }

  moveLayer(_id: string): void {
    /* Google polyline zIndex is fixed at create; skip reorder for MVP */
  }

  jumpTo(opts: EaseOpts): void {
    this.applyCamera(opts, false);
  }

  easeTo(opts: EaseOpts): void {
    this.applyCamera(opts, true);
  }

  private applyCamera(opts: EaseOpts, animate: boolean): void {
    if (this.destroyed) return;
    const cam: google.maps.CameraOptions = {};
    if (opts.center) {
      const c = asLngLat(opts.center);
      cam.center = { lat: c.lat, lng: c.lng };
    }
    if (opts.zoom != null) cam.zoom = opts.zoom;
    if (opts.pitch != null) cam.tilt = Math.max(0, Math.min(67.5, opts.pitch));
    if (opts.bearing != null) cam.heading = opts.bearing;
    if (animate && opts.center && opts.duration && opts.duration > 0) {
      const c = asLngLat(opts.center);
      this.gmap.panTo({ lat: c.lat, lng: c.lng });
      if (opts.zoom != null) this.gmap.setZoom(opts.zoom);
      if (opts.pitch != null) this.gmap.setTilt(Math.max(0, Math.min(67.5, opts.pitch)));
      if (opts.bearing != null) this.gmap.setHeading(opts.bearing);
    } else {
      this.gmap.moveCamera(cam);
    }
  }

  fitBounds(
    bounds:
      | GoogleLngLatBounds
      | [[number, number], [number, number]]
      | { getSouth?: () => number },
    opts: FitBoundsOpts = {},
  ): void {
    let gb: google.maps.LatLngBounds;
    if (bounds instanceof GoogleLngLatBounds) {
      gb = bounds.toGoogleBounds(this.maps);
    } else if (Array.isArray(bounds)) {
      gb = new this.maps.LatLngBounds(
        { lat: bounds[0][1], lng: bounds[0][0] },
        { lat: bounds[1][1], lng: bounds[1][0] },
      );
    } else if (
      bounds &&
      typeof (bounds as GoogleLngLatBounds).getSouth === "function" &&
      typeof (bounds as GoogleLngLatBounds).toGoogleBounds === "function"
    ) {
      gb = (bounds as GoogleLngLatBounds).toGoogleBounds(this.maps);
    } else {
      return;
    }

    const pad = opts.padding;
    let padding = 40;
    if (typeof pad === "number") padding = pad;
    else if (pad && typeof pad === "object") {
      padding = Math.max(pad.top || 0, pad.bottom || 0, pad.left || 0, pad.right || 0, 24);
    }

    this.gmap.fitBounds(gb, padding);
    if (opts.maxZoom != null) {
      this.maps.event.addListenerOnce(this.gmap, "idle", () => {
        const z = this.gmap.getZoom();
        if (z != null && z > opts.maxZoom!) this.gmap.setZoom(opts.maxZoom!);
        if (opts.pitch != null) this.gmap.setTilt(Math.max(0, Math.min(67.5, opts.pitch)));
        if (opts.bearing != null) this.gmap.setHeading(opts.bearing);
      });
    } else if (opts.pitch != null || opts.bearing != null) {
      this.maps.event.addListenerOnce(this.gmap, "idle", () => {
        if (opts.pitch != null) this.gmap.setTilt(Math.max(0, Math.min(67.5, opts.pitch)));
        if (opts.bearing != null) this.gmap.setHeading(opts.bearing);
      });
    }
  }

  remove(): void {
    this.destroyed = true;
    this.layers.forEach((layer) => layer.polyline.setMap(null));
    this.layers.clear();
    this.sources.clear();
    this.listeners.clear();
    this.maps.event.clearInstanceListeners(this.gmap);
    this.containerEl.innerHTML = "";
  }
}

/** No-op NavigationControl stand-in (Google uses built-in zoom). */
export class GoogleNavigationControl {
  onAdd(): HTMLElement {
    return document.createElement("div");
  }
  onRemove(): void {}
}
