/** HTML marker shim compatible with mapboxgl.Marker for Google Maps. */

export type GoogleMarkerOptions = {
  element?: HTMLElement;
  anchor?: string;
  offset?: [number, number];
  rotationAlignment?: string;
  pitchAlignment?: string;
};

export type GoogleMapHost = {
  gmap: google.maps.Map;
  maps: typeof google.maps;
  __mmdGoogleHost?: GoogleMapHost;
};

type OverlayHandle = {
  setMap: (map: google.maps.Map | null) => void;
  setPosition: (ll: google.maps.LatLng) => void;
  setRotation: (deg: number) => void;
  getElement: () => HTMLElement;
};

type OverlayCtor = new (
  el: HTMLElement,
  offset: [number, number],
  rotateWithMap: boolean,
  anchor: string,
) => OverlayHandle & google.maps.OverlayView;

let cachedOverlayCtor: OverlayCtor | null = null;

function buildOverlayClass(mapsApi: typeof google.maps): OverlayCtor {
  if (cachedOverlayCtor) return cachedOverlayCtor;

  class RuntimeHtmlOverlay extends mapsApi.OverlayView {
    private div: HTMLElement;
    private position: google.maps.LatLng | null = null;
    private offsetXY: [number, number];
    private rotation = 0;
    private rotateWithMap: boolean;
    private anchor: string;

    constructor(
      el: HTMLElement,
      offset: [number, number],
      rotateWithMap: boolean,
      anchor: string,
    ) {
      super();
      this.div = el;
      this.offsetXY = offset;
      this.rotateWithMap = rotateWithMap;
      this.anchor = anchor || "center";
      this.div.style.position = "absolute";
      this.div.style.willChange = "transform";
    }

    onAdd(): void {
      const panes = this.getPanes();
      panes?.overlayMouseTarget.appendChild(this.div);
    }

    draw(): void {
      if (!this.position) return;
      const projection = this.getProjection();
      if (!projection) return;
      const point = projection.fromLatLngToDivPixel(this.position);
      if (!point) return;
      const [ox, oy] = this.offsetXY;
      let rot = this.rotation;
      if (this.rotateWithMap) {
        const heading = this.getMap()?.getHeading?.() || 0;
        rot = this.rotation - heading;
      }
      const origin =
        this.anchor === "bottom"
          ? "translate(-50%, -100%)"
          : "translate(-50%, -50%)";
      this.div.style.left = `${point.x + ox}px`;
      this.div.style.top = `${point.y + oy}px`;
      this.div.style.transform = `${origin} rotate(${rot}deg)`;
    }

    onRemove(): void {
      this.div.remove();
    }

    setPosition(ll: google.maps.LatLng): void {
      this.position = ll;
      this.draw();
    }

    setRotation(deg: number): void {
      this.rotation = deg || 0;
      this.draw();
    }

    getElement(): HTMLElement {
      return this.div;
    }
  }

  cachedOverlayCtor = RuntimeHtmlOverlay as unknown as OverlayCtor;
  return cachedOverlayCtor;
}

export class GoogleHtmlMarker {
  private overlay: OverlayHandle | null = null;
  private el: HTMLElement;
  private offset: [number, number];
  private rotateWithMap: boolean;
  private anchor: string;
  private lng = 0;
  private lat = 0;
  private rotation = 0;
  private host: GoogleMapHost | null = null;
  /** Optional trip id stash used by atlas thumbs. */
  _tripId?: string;

  constructor(opts: GoogleMarkerOptions = {}) {
    this.el = opts.element || document.createElement("div");
    this.offset = opts.offset || [0, 0];
    this.rotateWithMap = opts.rotationAlignment === "map";
    this.anchor = opts.anchor || "center";
  }

  setLngLat(lngLat: [number, number] | { lng: number; lat: number }): this {
    if (Array.isArray(lngLat)) {
      this.lng = Number(lngLat[0]);
      this.lat = Number(lngLat[1]);
    } else {
      this.lng = Number(lngLat.lng);
      this.lat = Number(lngLat.lat);
    }
    if (this.overlay && this.host) {
      this.overlay.setPosition(new this.host.maps.LatLng(this.lat, this.lng));
    }
    return this;
  }

  setRotation(deg: number): this {
    this.rotation = deg || 0;
    this.overlay?.setRotation(this.rotation);
    return this;
  }

  getElement(): HTMLElement {
    return this.el;
  }

  addTo(mapLike: GoogleMapHost | { __mmdGoogleHost?: GoogleMapHost }): this {
    const host =
      (mapLike as { __mmdGoogleHost?: GoogleMapHost }).__mmdGoogleHost ||
      (mapLike as GoogleMapHost);
    if (!host?.gmap || !host?.maps) {
      throw new Error("GoogleHtmlMarker.addTo requires a Google map host");
    }
    this.host = host;
    if (this.overlay) {
      this.overlay.setMap(null);
    }
    const Overlay = buildOverlayClass(host.maps);
    this.overlay = new Overlay(this.el, this.offset, this.rotateWithMap, this.anchor);
    this.overlay.setMap(host.gmap);
    this.overlay.setPosition(new host.maps.LatLng(this.lat, this.lng));
    this.overlay.setRotation(this.rotation);
    return this;
  }

  remove(): void {
    if (this.overlay) {
      this.overlay.setMap(null);
      this.overlay = null;
    }
    this.host = null;
  }
}
